window.AUTH=window.AUTH||{};window.AUTH["15-1293"]={"d":"15-1293","id":"2016/15-1293","n":"Matal v. Tam","src":["osg"],"briefs":[{"k":"petitioner","label":"Brief for the petitioner","date":"2016-11-09","url":"https://www.justice.gov/osg/media/867366/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/lee-v-tam-3","n":75},{"k":"reply","label":"Reply brief for the petitioner","date":"2017-01-09","url":"https://www.justice.gov/osg/media/873531/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/lee-v-tam-4","n":56}],"opinion":null,"tr":true,"items":[{"t":"case","label":"Agency for Int’l Dev. v. Alliance for Open Soc’y Int’l, Inc.","cite":"133 S. Ct. 2321","y":2013,"id":"2012/12-10","sc":1,"sum":"The Court held that it was a violation of the First Amendment to withhold funding from non-government organizations if they did not institute an anti-prostitution policy.","sumSrc":"Oyez","by":{"0":"11, 31, 32, 33, 34","1":"15"}},{"t":"case","label":"American Freedom Def. Initiative v. Massachusetts Bay Transp. Auth.","cite":"781 F.3d 571","y":2015,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/781/571/","sum":"Explaining that the First Circuit has “rejected the contention that the demeaning or disparaging guideline is an attempt by the government ‘to give one group an advantage over another in the marketplace of ideas’ ”.","sumSrc":"brief:0","by":{"0":"45, 46","1":"11"}},{"t":"case","label":"B & B Hardware, Inc. v. Hargis Indus., Inc.","cite":"135 S. Ct. 1293","y":2015,"id":"2014/13-352","sc":1,"sum":"The Court held that a decision on an issue by an administrative agency can preclude re-litigation of that issue in federal court.","sumSrc":"Oyez","by":{"0":"2, 3, 20, 35"}},{"t":"case","label":"Broadrick v. Oklahoma","cite":"413 U.S. 601","y":1973,"id":"1972/71-1639","sc":1,"sum":"Section 818 of the Oklahoma statute is not unconstitutional on its face. CSC v. Letter Carriers, ante, p. 548.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"51"}},{"t":"case","label":"Canal Co. v. Clark","cite":"80 U.S. 311","y":1872,"id":"scdb/1871-105","sc":1,"sum":"In the northeastern section of Pennsylvania there exists a place or region to which from early times the name of Lorckaworna, or Lackawanna, seems, on the few occasions when the place is mentioned, to have been given. As early as 1793, the diary of William Colbert, a pioneer preacher of the Methodists, makes record of his meeting a person who lived at “Lackawanna,” and of his crossing a mountain and getting there …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"47"}},{"t":"case","label":"Central Hudson Gas & Elec. Corp. v. Public Serv. Comm’n","cite":"447 U.S. 557","y":1980,"id":"1979/79-565","sc":1,"sum":"The Court overruled the Court of Appeals of New York and held that the New York's ban violated the right to commercial speech. Writing for the majority, Justice Lewis F. Powell cited the protections for \"commercial speech from unwarranted governmental regulation\" set forth in Virginia Pharmacy Board v. Virginia Citizens Consumer Council .","sumSrc":"Oyez","by":{"0":"48"}},{"t":"case","label":"Davenport v. Washington Educ. Ass’n","cite":"551 U.S. 177","y":2007,"id":"2006/05-1589","sc":1,"sum":"The Court ruled that the First Amendment allows a state to require public-sector unions collecting \"agency-shop\" fees from non-union employees to obtain permission from the employees before using the money for political purposes.","sumSrc":"Oyez","by":{"0":"9, 17, 35, 41, 44","1":"14"}},{"t":"case","label":"Eldred v. Ashcroft","cite":"537 U.S. 186","y":2003,"id":"2002/01-618","sc":1,"sum":"The Court held that Congress acted within its authority and did not transgress constitutional limitations in placing existing and future copyrights in parity in the CTEA.","sumSrc":"Oyez","by":{"0":"47","1":"16"}},{"t":"case","label":"Hanover Star Milling Co. v. Metcalf","cite":"240 U.S. 403","y":1916,"id":"scdb/1915-112","sc":1,"sum":"Two District Courts in different circuits having'granted temporary -injunctions, and both Circuit Courts of Appeals having reversed upon grounds that went to the merits and differed upon fundamental questionsaffecting the same trade-mark,' writs of.certiorari.were allowed by this court before final decrees, notwithstanding the general rule to the contrary.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"Harris v. McRae","cite":"448 U.S. 297","y":1980,"id":"1979/79-1268","sc":1,"sum":"The Court held that states participating in the Medicaid program were not obligated to fund medically necessary abortions under Title XIX.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Heart of Atlanta Motel, Inc. v. United States","cite":"379 U.S. 241","y":1964,"id":"1964/515","sc":1,"sum":"The Court found that hotels did not have the right to discriminate against black guests under Title II of the Civil Rights Act of 1964.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Katzenbach v. McClung","cite":"379 U.S. 294","y":1964,"id":"1964/543","sc":1,"sum":"The Court held McClung could be barred from discriminating against African Americans under the Civil Rights Act of 1964.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Legal Servs. Corp. v. Velazquez","cite":"531 U.S. 533","y":2001,"id":"2000/99-603","sc":1,"sum":"The Court held that the funding provision that limited arguments legal services attorneys were allowed to make on behalf of indigent welfare claimants violated the First Amendment by regulating private speech and insulating federal law from legitimate judicial challenge.","sumSrc":"Oyez","by":{"0":"33, 43","1":"13"}},{"t":"case","label":"Maher v. Roe","cite":"432 U.S. 464","y":1977,"id":"1976/75-1440","sc":1,"sum":"In a 6-to-3 decision, the Court held that the Connecticut law placed no obstacles in the pregnant woman's path to an abortion, and that it did not \"impinge upon the fundamental right recognized in Roe.\" The Court noted that there was a distinction between direct state interference with a protected activity and \"state encouragement of alternative activity consonant with legislative policy.\" Holding that financial need alone did not identify a suspect class under the Equal Protection Clause, the Court found that the law was \"rationally related\" to a legitimate state interest and survived scrutiny under the Fourteenth Amendment.","sumSrc":"Oyez","by":{"0":"14"}},{"t":"case","label":"Moseley v. V Secret Catalogue, Inc.","cite":"537 U.S. 418","y":2003,"id":"2002/01-1015","sc":1,"sum":"Justice John Paul Stevens delivered the opinion for a unanimous Court with respect to parts I, II, and IV of the opinion, which held that the FTDA requires proof of actual dilution.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"National Endowment for the Arts v. Finley","cite":"524 U.S. 569","y":1998,"id":"1997/97-371","sc":1,"sum":"In an 8-to-1 opinion the Court held that, unlike direct sovereign regulation of speech, Congress enjoys wide latitude when setting spending priorities which may indirectly affect certain forms of expression. The funding of one activity believed to be in the public interest, to the exclusion of another, does not constitute viewpoint discrimination.","sumSrc":"Oyez","by":{"0":"passim","1":"10, 22"}},{"t":"case","label":"Park ’N Fly, Inc. v. Dollar Park & Fly, Inc.","cite":"469 U.S. 189","y":1985,"id":"1984/83-1132","sc":1,"ar":1,"sum":"The holder of a registered mark may rely on incontestability to enjoin infringement, and an infringement action may not be defended on the grounds that the mark is merely descriptive.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 28","1":"6, 8"}},{"t":"case","label":"Pleasant Grove City v. Summum","cite":"555 U.S. 460","y":2009,"id":"2008/07-665","sc":1,"sum":"The Court held that a city's refusal to place an organization's monument in a public park is not a violation the organization's First Amendment rights.","sumSrc":"Oyez","by":{"0":"19, 42"}},{"t":"case","label":"Pro-Football Inc. v. Blackhorse","cite":"112 F. Supp. 3d 439","y":2015,"court":"E.D. Va.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/112/439/","by":{"0":"39, 50"}},{"t":"case","label":"Qualitex Co. v. Jacobson Prods. Co.","cite":"514 U.S. 159","y":1995,"id":"1994/93-1577","sc":1,"sum":"The Lanham Act permits the registration of a trademark that consists, purely and simply, of a color.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47"}},{"t":"case","label":"R.A.V. v. City of St. Paul","cite":"505 U.S. 377","y":1992,"id":"1991/90-7675","sc":1,"sum":"The Court found a Minnesota ordinance violated the First Amendment because the ordinance was overly broad in the content-based speech it prohibited.","sumSrc":"Oyez","by":{"0":"45","1":"5, 11"}},{"t":"case","label":"Regan v. Taxation With Representation of Wash.","cite":"461 U.S. 540","y":1983,"id":"1982/81-2338","sc":1,"sum":"No and no. Justice William H. Rehnquist authored the opinion for a unanimous court. Allowing a non-profit to solicit tax-deductible donations is a form of paying for its operations.","sumSrc":"Oyez","by":{"0":"passim","1":"12, 13"}},{"t":"case","label":"Ridley v. Massachusetts Bay Transp. Auth.","cite":"390 F.3d 65","y":2004,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/390/65/","by":{"0":"45, 46","1":"11"}},{"t":"case","label":"Rosenberger v. Rector & Visitors of Univ. of Va.","cite":"515 U.S. 819","y":1995,"id":"1994/94-329","sc":1,"sum":"The Court, in a 5-to-4 opinion, held that the University's denial of funding to Rosenberger, due to the content of his message, imposed a financial burden on his speech and amounted to viewpoint discrimination. The Court noted that no matter how scarce University publication funding may be, if it chooses to promote speech at all, it must promote all forms of it equally.","sumSrc":"Oyez","by":{"0":"46","1":"4"}},{"t":"case","label":"Rust v. Sullivan","cite":"500 U.S. 173","y":1991,"id":"1990/89-1391","sc":1,"sum":"The Court held that the \"regulations promulgated by the Secretary [of HHS] do not raise the sort of 'grave and doubtful constitutional questions' that would lead us to assume Congress did not intend to authorize their issuance.\" Should government subsidize one protected right (family planning), as it does in this case, it does not follow that government must subsidize analogous counterpart rights (abortion services).","sumSrc":"Oyez","by":{"0":"passim","1":"3, 4, 12, 13, 17"}},{"t":"case","label":"San Francisco Arts & Athletics, Inc. v. United States Olympic Comm.","cite":"483 U.S. 522","y":1987,"id":"1986/86-270","sc":1,"sum":"Currently unavailable.","sumSrc":"Oyez","by":{"0":"48","1":"9, 16"}},{"t":"case","label":"Two Pesos, Inc. v. Taco Cabana, Inc.","cite":"505 U.S. 763","y":1992,"id":"1991/91-971","sc":1,"sum":"The Supreme Court held that trade dress can be protected under the Lanham Act based on inherent distinctiveness even if there is no proof of a secondary meaning. Recovery is usually available for trademark infringement without a secondary meaning, and there is no persuasive reason for treating trade dress differently from other types of trademark.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"United Drug Co. v. Theodore Rectanus Co.","cite":"248 U.S. 90","y":1918,"id":"scdb/1918-017","sc":1,"sum":"A right of trade-mark is not a right in gross; it exists only as appurtenant to an established business and for the protection of the good will thereof.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"United States v. American Library Ass’n","cite":"539 U.S. 194","y":2003,"id":"2002/02-361","sc":1,"sum":"In a 6-3 judgment delivered by Chief Justice William H. Rehnquist, the Court held that, because public libraries' use of Internet filtering software does not violate their patrons' First Amendment rights, CIPA does not induce libraries to violate the Constitution and is a valid exercise of Congress's spending power. Justices Sandra Day O'Connor, Antonin Scalia, and Clarence Thomas joined the Chief Justice's opinion.","sumSrc":"Oyez","by":{"0":"16, 17, 30, 49"}},{"t":"case","label":"Wal-Mart Stores, Inc. v. Samara Bros., Inc.","cite":"529 U.S. 205","y":2000,"id":"1999/99-150","sc":1,"sum":"The Court held that \"[i]n a section 43(a) action for infringement of unregistered trade dress, a product's design is distinctive, and therefore protectible, only upon a showing of secondary meaning.","sumSrc":"Oyez","by":{"0":"47","1":"9"}},{"t":"case","label":"Walker v. Texas Div., Sons of Confederate Veterans, Inc.","cite":"135 S. Ct. 2239","y":2015,"id":"2014/14-144","sc":1,"sum":"Texas' specialty license plates constitute government speech that does not require viewpoint neutrality under the First Amendment.","sumSrc":"Oyez","by":{"0":"passim","1":"9, 10, 13, 15"}},{"t":"case","label":"Wooley v. Maynard","cite":"430 U.S. 705","y":1977,"id":"1976/75-1453","sc":1,"sum":"In a 6-to-3 decision, the Court held that New Hampshire could not constitutionally require citizens to display the state motto upon their vehicle license plates.","sumSrc":"Oyez","by":{"0":"19, 38, 40, 43","1":"9"}},{"t":"case","label":"Case—Continued: Ysursa v. Pocatello Educ. Ass’n","cite":"555 U.S. 353","y":2009,"id":"2008/07-869","sc":1,"ar":2,"sum":"The Court found that provisions of Idaho's Voluntary Contributions Act which prohibit payroll deductions for \"political activities\" did not violate the First Amendment when applied to local government employees.","sumSrc":"Oyez","by":{"0":"passim","1":"3, 13"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"0":"24","1":"passim"}},{"t":"usc","label":"15 U.S.C. § 1051","url":"https://www.law.cornell.edu/uscode/text/15/1051","subs":["(a)","(a)(1)"],"stext":{"head":"§1051. Application for registration; verification","paras":[[0,"(a) Application for use of trademark"],[0,"(1) The owner of a trademark used in commerce may request registration of its trademark on the principal register hereby established by paying the prescribed fee and filing in the Patent and Trademark Office an application and a verified statement, in such form as may be prescribed by the Director, and such number of specimens or facsimiles of the mark as used as may be required by the Director."],[0,"(2) The application shall include specification of the applicant's domicile and citizenship, the date of the applicant's first use of the mark, the date of the applicant's first use of the mark in commerce, the goods in connection with which the mark is used, and a drawing of the mark."],[0,"(3) The statement shall be verified by the applicant and specify that—"],[1,"(A) the person making the verification believes that he or she, or the juristic person in whose behalf he or she makes the verification, to be the owner of the mark sought to be registered;"],[1,"(B) to the best of the verifier's knowledge and belief, the facts recited in the application are accurate;"],[1,"(C) the mark is in use in commerce; and"],[1,"(D) to the best of the verifier's knowledge and belief, no other person has the right to use such mark in commerce either in the identical form thereof or in such near resemblance thereto as to be likely, when used on or in connection with the goods of such other person, to cause confusion, or to cause mistake, or to deceive, except that, in the case of every application claiming concurrent use, the applicant shall—"],[2,"(i) state exceptions to the claim of exclusive use; and"],[2,"(ii) shall 1 specify, to the extent of the verifier's knowledge—"],[3,"(I) any concurrent use by others;"],[3,"(II) the goods on or in connection with which and the areas in which each concurrent use exists;"],[3,"(III) the periods of each use; and"],[3,"(IV) the goods and area for which the applicant desires registration."],[0,"(4) The applicant shall comply with such rules or regulations as may be prescribed by the Director. The Director shall promulgate rules prescribing the requirements for the application and for obtaining a filing date herein."],[0,"(b) Application for bona fide intention to use trademark"],[0,"(1) A person who has a bona fide intention, under circumstances showing the good faith of such person, to use a trademark in commerce may request registration of its trademark on the principal register hereby established by paying the prescribed fee and filing in the Patent and Trademark Office an application and a verified statement, in such form as may be prescribed by the Director."],[0,"(2) The application shall include specification of the applicant's domicile and citizenship, the goods in connection with which the applicant has a bona fide intention to use the mark, and a drawing of the mark."],[0,"(3) The statement shall be verified by the applicant and specify—"],[1,"(A) that the person making the verification believes that he or she, or the juristic person in whose behalf he or she makes the verification, to be entitled to use the mark in commerce;"],[1,"(B) the applicant's bona fide intention to use the mark in commerce;"],[1,"(C) that, to the best of the verifier's knowledge and belief, the facts recited in the application are accurate; and"],[1,"(D) that, to the best of the verifier's knowledge and belief, no other person has the right to use such mark in commerce either in the identical form thereof or in such near resemblance thereto as to be likely, when used on or in connection with the goods of such other person, to cause confusion, or to cause mistake, or to deceive."],[0,"Except for applications filed pursuant to section 1126 of this title, no mark shall be registered until the applicant has met the requirements of subsections (c) and (d) of this section."],[0,"(4) The applicant shall comply with such rules or regulations as may be prescribed by the Director. The Director shall promulgate rules prescribing the requirements for the application and for obtaining a filing date herein."],[0,"(c) Amendment of application under subsection (b) to conform to requirements of subsection (a)"],[0,"At any time during examination of an application filed under subsection (b), an applicant who has made use of the mark in commerce may claim the benefits of such use for purposes of this chapter, by amending his or her application to bring it into conformity with the requirements of subsection (a)."],[0,"(d) Verified statement that trademark is used in commerce"],[0,"(1) Within six months after the date on which the notice of allowance with respect to a mark is issued under section 1063(b)(2) of this title to an applicant under subsection (b) of this section, the applicant shall file in the Patent and Trademark Office, together with such number of specimens or facsimiles of the mark as used in commerce as may be required by the Director and payment of the prescribed fee, a verified statement that the mark is in use in commerce and specifying the date of the applicant's first use of the mark in commerce and those goods or services specified in the notice of allowance on or in connection with which the mark is used in commerce. Subject to examination and acceptance of the statement of use, the mark shall be registered in the Patent and Trademark Office, a certificate of registration shall be issued for those goods or services recited in the statement of use for which the mark is entitled to registration, and notice of registration shall be published in the Official Gazette of the Patent and Trademark Office. Such examination may include an examination of the factors set forth in subsections (a) through (e) of section 1052 of this title. The notice of registration shall specify the goods or services for which the mark is registered."],[0,"(2) The Director shall extend, for one additional 6-month period, the time for filing the statement of use under paragraph (1), upon written request of the applicant before the expiration of the 6-month period provided in paragraph (1). In addition to an extension under the preceding sentence, the Director may, upon a showing of good cause by the applicant, further extend the time for filing the statement of use under paragraph (1) for periods aggregating not more than 24 months, pursuant to written request of the applicant made before the expiration of the last extension granted under this paragraph. Any request for an extension under this paragraph shall be accompanied by a verified statement that the applicant has a continued bona fide intention to use the mark in commerce and specifying those goods or services identified in the notice of allowance on or in connection with which the applicant has a continued bona fide intention to use the mark in commerce. Any request for an extension under this paragraph shall be accompanied by payment of the prescribed fee. The Director shall issue regulations setting forth guidelines for determining what constitutes good cause for purposes of this paragraph."],[0,"(3) The Director shall notify any applicant who files a statement of use of the acceptance or refusal thereof and, if the statement of use is refused, the reasons for the refusal. An applicant may amend the statement of use."],[0,"(4) The failure to timely file a verified statement of use under paragraph (1) or an extension request under paragraph (2) shall result in abandonment of the application, unless it can be shown to the satisfaction of the Director that the delay in responding was unintentional, in which case the time for filing may be extended, but for a period not to exceed the period specified in paragraphs (1) and (2) for filing a statement of use."],[0,"(e) Designation of resident for service of process and notices"],[0,"If the applicant is not domiciled in the United States the applicant may designate, by a document filed in the United States Patent and Trademark Office, the name and address of a person resident in the United States on whom may be served notices or process in proceedings affecting the mark. Such notices or process may be served upon the person so designated by leaving with that person or mailing to that person a copy thereof at the address specified in the last designation so filed. If the person so designated cannot be found at the address given in the last designation, or if the registrant does not designate by a document filed in the United States Patent and Trademark Office the name and address of a person resident in the United States on whom may be served notices or process in proceedings affecting the mark, such notices or process may be served on the Director."],[0,"(f) Third-party submission of evidence"],[0,"A third party may submit for consideration for inclusion in the record of an application evidence relevant to a ground for refusal of registration. The third-party submission shall identify the ground for refusal and include a concise description of each piece of evidence submitted in support of each identified ground for refusal. Not later than 2 months after the date on which the submission is filed, the Director shall determine whether the evidence should be included in the record of the application. The Director shall establish by regulation appropriate procedures for the consideration of evidence submitted by a third party under this subsection and may prescribe a fee to accompany the submission. If the Director determines that the third-party evidence should be included in the record of the application, only the evidence and the ground for refusal to which the evidence relates may be so included. Any determination by the Director whether or not to include evidence in the record of an application shall be final and non-reviewable, and a determination to include or to not include evidence in the record shall not prejudice any party's right to raise any issue and rely on any evidence in any other proceeding."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1051?type=usc&year=mostrecent&link-type=html"},"head":"§1051. Application for registration; verification","tname":"Commerce and Trade","by":{"0":"3, 3, 10, 22, 49, 3, 10, 22, 49","1":"7, 16, 6"}},{"t":"usc","label":"15 U.S.C. § 1052","url":"https://www.law.cornell.edu/uscode/text/15/1052","subs":["(a)","(b)","(c)","(d)","(e)(1)","(e)(5)"],"stext":{"head":"§1052. Trademarks registrable on principal register; concurrent registration","paras":[[0,"No trademark by which the goods of the applicant may be distinguished from the goods of others shall be refused registration on the principal register on account of its nature unless it—"],[0,"(a) Consists of or comprises immoral, deceptive, or scandalous matter; or matter which may disparage or falsely suggest a connection with persons, living or dead, institutions, beliefs, or national symbols, or bring them into contempt, or disrepute; or a geographical indication which, when used on or in connection with wines or spirits, identifies a place other than the origin of the goods and is first used on or in connection with wines or spirits by the applicant on or after one year after the date on which the WTO Agreement (as defined in section 3501(9) of title 19) enters into force with respect to the United States."],[0,"(b) Consists of or comprises the flag or coat of arms or other insignia of the United States, or of any State or municipality, or of any foreign nation, or any simulation thereof."],[0,"(c) Consists of or comprises a name, portrait, or signature identifying a particular living individual except by his written consent, or the name, signature, or portrait of a deceased President of the United States during the life of his widow, if any, except by the written consent of the widow."],[0,"(d) Consists of or comprises a mark which so resembles a mark registered in the Patent and Trademark Office, or a mark or trade name previously used in the United States by another and not abandoned, as to be likely, when used on or in connection with the goods of the applicant, to cause confusion, or to cause mistake, or to deceive: Provided, That if the Director determines that confusion, mistake, or deception is not likely to result from the continued use by more than one person of the same or similar marks under conditions and limitations as to the mode or place of use of the marks or the goods on or in connection with which such marks are used, concurrent registrations may be issued to such persons when they have become entitled to use such marks as a result of their concurrent lawful use in commerce prior to (1) the earliest of the filing dates of the applications pending or of any registration issued under this chapter; (2) July 5, 1947, in the case of registrations previously issued under the Act of March 3, 1881, or February 20, 1905, and continuing in full force and effect on that date; or (3) July 5, 1947, in the case of applications filed under the Act of February 20, 1905, and registered after July 5, 1947. Use prior to the filing date of any pending application or a registration shall not be required when the owner of such application or registration consents to the grant of a concurrent registration to the applicant. Concurrent registrations may also be issued by the Director when a court of competent jurisdiction has finally determined that more than one person is entitled to use the same or similar marks in commerce. In issuing concurrent registrations, the Director shall prescribe conditions and limitations as to the mode or place of use of the mark or the goods on or in connection with which such mark is registered to the respective persons."],[0,"(e) Consists of a mark which (1) when used on or in connection with the goods of the applicant is merely descriptive or deceptively misdescriptive of them, (2) when used on or in connection with the goods of the applicant is primarily geographically descriptive of them, except as indications of regional origin may be registrable under section 1054 of this title, (3) when used on or in connection with the goods of the applicant is primarily geographically deceptively misdescriptive of them, (4) is primarily merely a surname, or (5) comprises any matter that, as a whole, is functional."],[0,"(f) Except as expressly excluded in subsections (a), (b), (c), (d), (e)(3), and (e)(5) of this section, nothing in this chapter shall prevent the registration of a mark used by the applicant which has become distinctive of the applicant's goods in commerce. The Director may accept as prima facie evidence that the mark has become distinctive, as used on or in connection with the applicant's goods in commerce, proof of substantially exclusive and continuous use thereof as a mark by the applicant in commerce for the five years before the date on which the claim of distinctiveness is made. Nothing in this section shall prevent the registration of a mark which, when used on or in connection with the goods of the applicant, is primarily geographically deceptively misdescriptive of them, and which became distinctive of the applicant's goods in commerce before December 8, 1993."],[0,"A mark which would be likely to cause dilution by blurring or dilution by tarnishment under section 1125(c) of this title, may be refused registration only pursuant to a proceeding brought under section 1063 of this title. A registration for a mark which would be likely to cause dilution by blurring or dilution by tarnishment under section 1125(c) of this title, may be canceled pursuant to a proceeding brought under either section 1064 of this title or section 1092 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1052?type=usc&year=mostrecent&link-type=html"},"head":"§1052. Trademarks registrable on principal register; concurrent registration","tname":"Commerce and Trade","by":{"0":"3, 10, 22, 49, 3, 10, 22, 49, 3, 10, 22, 49, 3, 10, 22, 49, 3, 10, 22, 49, 3, 10, 22, 49, 3, 10, 22, 49, 3, 10, 22, 49","1":"2, passim, 21"}},{"t":"usc","label":"15 U.S.C. § 1053","url":"https://www.law.cornell.edu/uscode/text/15/1053","by":{"0":"3, 10, 22, 49"}},{"t":"usc","label":"15 U.S.C. § 1057","url":"https://www.law.cornell.edu/uscode/text/15/1057","subs":["(a)","(b)"],"stext":{"head":"§1057. Certificates of registration","paras":[[0,"(a) Issuance and form"],[0,"Certificates of registration of marks registered upon the principal register shall be issued in the name of the United States of America, under the seal of the United States Patent and Trademark Office, and shall be signed by the Director or have his signature placed thereon, and a record thereof shall be kept in the United States Patent and Trademark Office. The registration shall reproduce the mark, and state that the mark is registered on the principal register under this chapter, the date of the first use of the mark, the date of the first use of the mark in commerce, the particular goods or services for which it is registered, the number and date of the registration, the term thereof, the date on which the application for registration was received in the United States Patent and Trademark Office, and any conditions and limitations that may be imposed in the registration."],[0,"(b) Certificate as prima facie evidence"],[0,"A certificate of registration of a mark upon the principal register provided by this chapter shall be prima facie evidence of the validity of the registered mark and of the registration of the mark, of the owner's ownership of the mark, and of the owner's exclusive right to use the registered mark in commerce on or in connection with the goods or services specified in the certificate, subject to any conditions or limitations stated in the certificate."],[0,"(c) Application to register mark considered constructive use"],[0,"Contingent on the registration of a mark on the principal register provided by this chapter, the filing of the application to register such mark shall constitute constructive use of the mark, conferring a right of priority, nationwide in effect, on or in connection with the goods or services specified in the registration against any other person except for a person whose mark has not been abandoned and who, prior to such filing—"],[1,"(1) has used the mark;"],[1,"(2) has filed an application to register the mark which is pending or has resulted in registration of the mark; or"],[1,"(3) has filed a foreign application to register the mark on the basis of which he or she has acquired a right of priority, and timely files an application under section 1126(d) of this title to register the mark which is pending or has resulted in registration of the mark."],[0,"(d) Issuance to assignee"],[0,"A certificate of registration of a mark may be issued to the assignee of the applicant, but the assignment must first be recorded in the United States Patent and Trademark Office. In case of change of ownership the Director shall, at the request of the owner and upon a proper showing and the payment of the prescribed fee, issue to such assignee a new certificate of registration of the said mark in the name of such assignee, and for the unexpired part of the original period."],[0,"(e) Surrender, cancellation, or amendment by owner"],[0,"Upon application of the owner the Director may permit any registration to be surrendered for cancellation, and upon cancellation appropriate entry shall be made in the records of the United States Patent and Trademark Office. Upon application of the owner and payment of the prescribed fee, the Director for good cause may permit any registration to be amended or to be disclaimed in part: Provided, That the amendment or disclaimer does not alter materially the character of the mark. Appropriate entry shall be made in the records of the United States Patent and Trademark Office and upon the certificate of registration."],[0,"(f) Copies of United States Patent and Trademark Office records as evidence"],[0,"Copies of any records, books, papers, or drawings belonging to the United States Patent and Trademark Office relating to marks, and copies of registrations, when authenticated by the seal of the United States Patent and Trademark Office and certified by the Director, or in his name by an employee of the Office duly designated by the Director, shall be evidence in all cases wherein the originals would be evidence; and any person making application therefor and paying the prescribed fee shall have such copies."],[0,"(g) Correction of United States Patent and Trademark Office mistake"],[0,"Whenever a material mistake in a registration, incurred through the fault of the United States Patent and Trademark Office, is clearly disclosed by the records of the Office a certificate stating the fact and nature of such mistake shall be issued without charge and recorded and a printed copy thereof shall be attached to each printed copy of the registration and such corrected registration shall thereafter have the same effect as if the same had been originally issued in such corrected form, or in the discretion of the Director a new certificate of registration may be issued without charge. All certificates of correction heretofore issued in accordance with the rules of the United States Patent and Trademark Office and the registrations to which they are attached shall have the same force and effect as if such certificates and their issue had been specifically authorized by statute."],[0,"(h) Correction of applicant's mistake"],[0,"Whenever a mistake has been made in a registration and a showing has been made that such mistake occurred in good faith through the fault of the applicant, the Director is authorized to issue a certificate of correction or, in his discretion, a new certificate upon the payment of the prescribed fee: Provided, That the correction does not involve such changes in the registration as to require republication of the mark."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1057?type=usc&year=mostrecent&link-type=html"},"head":"§1057. Certificates of registration","tname":"Commerce and Trade","by":{"0":"3, 10, 22, 49, 3, 10, 22, 27","1":"6, 7"}},{"t":"usc","label":"15 U.S.C. § 1062","url":"https://www.law.cornell.edu/uscode/text/15/1062","stext":{"head":"§1062. Publication","paras":[[0,"(a) Examination and publication"],[0,"Upon the filing of an application for registration and payment of the prescribed fee, the Director shall refer the application to the examiner in charge of the registration of marks, who shall cause an examination to be made and, if on such examination it shall appear that the applicant is entitled to registration, or would be entitled to registration upon the acceptance of the statement of use required by section 1051(d) of this title, the Director shall cause the mark to be published in the Official Gazette of the Patent and Trademark Office: Provided, That in the case of an applicant claiming concurrent use, or in the case of an application to be placed in an interference as provided for in section 1066 of this title the mark, if otherwise registrable, may be published subject to the determination of the rights of the parties to such proceedings."],[0,"(b) Refusal of registration; amendment of application; abandonment; extensions of time to respond"],[0,"(1) If the applicant is found not entitled to registration, the examiner shall notify the applicant thereof and of the reasons therefor. The applicant may reply or amend the application, which shall then be reexamined. This procedure may be repeated until the examiner finally refuses registration of the mark or the application is abandoned as described in paragraph (2)."],[0,"(2) After notification under paragraph (1), the applicant shall have a period of 6 months in which to reply or amend the application, or such shorter time that is not less than 60 days, as prescribed by the Director by regulation. If the applicant fails to reply or amend or appeal within the relevant time period, including any extension under paragraph (3), the application shall be deemed to have been abandoned, unless it can be shown to the satisfaction of the Director that the delay in responding was unintentional, in which case the application may be revived and such time may be extended. The Director may prescribe a fee to accompany any request to revive."],[0,"(3) The Director shall provide, by regulation, for extensions of time to respond to the examiner for any time period under paragraph (2) that is less than 6 months. The Director shall allow the applicant to obtain extensions of time to reply or amend aggregating 6 months from the date of notification under paragraph (1) when the applicant so requests. However, the Director may set by regulation the time for individual periods of extension, and prescribe a fee, by regulation, for any extension request. Any request for extension shall be filed on or before the date on which a reply or amendment is due under paragraph (1)."],[0,"(c) Republication of marks registered under prior acts"],[0,"A registrant of a mark registered under the provisions of the Act of March 3, 1881, or the Act of February 20, 1905, may, at any time prior to the expiration of the registration thereof, upon the payment of the prescribed fee file with the Director an affidavit setting forth those goods stated in the registration on which said mark is in use in commerce and that the registrant claims the benefits of this chapter for said mark. The Director shall publish notice thereof with a reproduction of said mark in the Official Gazette, and notify the registrant of such publication and of the requirement for the affidavit of use or nonuse as provided for in subsection (b) of section 1058 of this title. Marks published under this subsection shall not be subject to the provisions of section 1063 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1062?type=usc&year=mostrecent&link-type=html"},"head":"§1062. Publication","tname":"Commerce and Trade","by":{"0":"3, 10, 22","1":"6"}},{"t":"usc","label":"15 U.S.C. § 1063","url":"https://www.law.cornell.edu/uscode/text/15/1063","by":{"0":"52"}},{"t":"usc","label":"15 U.S.C. § 1064","url":"https://www.law.cornell.edu/uscode/text/15/1064","stext":{"head":"§1064. Cancellation of registration","paras":[[0,"A petition to cancel a registration of a mark, stating the grounds relied upon, may, upon payment of the prescribed fee, be filed as follows by any person who believes that he is or will be damaged, including as a result of a likelihood of dilution by blurring or dilution by tarnishment under section 1125(c) of this title, by the registration of a mark on the principal register established by this chapter, or under the Act of March 3, 1881, or the Act of February 20, 1905:"],[1,"(1) Within five years from the date of the registration of the mark under this chapter."],[1,"(2) Within five years from the date of publication under section 1062(c) of this title of a mark registered under the Act of March 3, 1881, or the Act of February 20, 1905."],[1,"(3) At any time if the registered mark becomes the generic name for the goods or services, or a portion thereof, for which it is registered, or is functional, or has been abandoned, or its registration was obtained fraudulently or contrary to the provisions of section 1054 of this title or of subsection (a), (b), or (c) of section 1052 of this title for a registration under this chapter, or contrary to similar prohibitory provisions of such prior Acts for a registration under such Acts, or if the registered mark is being used by, or with the permission of, the registrant so as to misrepresent the source of the goods or services on or in connection with which the mark is used. If the registered mark becomes the generic name for less than all of the goods or services for which it is registered, a petition to cancel the registration for only those goods or services may be filed. A registered mark shall not be deemed to be the generic name of goods or services solely because such mark is also used as a name of or to identify a unique product or service. The primary significance of the registered mark to the relevant public rather than purchaser motivation shall be the test for determining whether the registered mark has become the generic name of goods or services on or in connection with which it has been used."],[1,"(4) At any time if the mark is registered under the Act of March 3, 1881, or the Act of February 20, 1905, and has not been published under the provisions of subsection (c) of section 1062 of this title."],[1,"(5) At any time in the case of a certification mark on the ground that the registrant (A) does not control, or is not able legitimately to exercise control over, the use of such mark, or (B) engages in the production or marketing of any goods or services to which the certification mark is applied, or (C) permits the use of the certification mark for purposes other than to certify, or (D) discriminately refuses to certify or to continue to certify the goods or services of any person who maintains the standards or conditions which such mark certifies."],[1,"(6) At any time after the 3-year period following the date of registration, if the registered mark has never been used in commerce on or in connection with some or all of the goods or services recited in the registration:"],[0,"Provided, That the Federal Trade Commission may apply to cancel on the grounds specified in paragraphs (3) and (5) of this section any mark registered on the principal register established by this chapter, and the prescribed fee shall not be required. Nothing in paragraph (5) shall be deemed to prohibit the registrant from using its certification mark in advertising or promoting recognition of the certification program or of the goods or services meeting the certification standards of the registrant. Such uses of the certification mark shall not be grounds for cancellation under paragraph (5), so long as the registrant does not itself produce, manufacture, or sell any of the certified goods or services to which its identical certification mark is applied. Nothing in paragraph (6) shall be construed to limit the timing applicable to any other ground for cancellation. A registration under section 1126(e) or 1141f of this title shall not be cancelled pursuant to paragraph (6) if the registrant demonstrates that any nonuse is due to special circumstances that excuse such nonuse."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1064?type=usc&year=mostrecent&link-type=html"},"head":"§1064. Cancellation of registration","tname":"Commerce and Trade","by":{"0":"52","1":"23"}},{"t":"usc","label":"15 U.S.C. § 1065","url":"https://www.law.cornell.edu/uscode/text/15/1065","by":{"0":"52"}},{"t":"usc","label":"15 U.S.C. § 1067","url":"https://www.law.cornell.edu/uscode/text/15/1067","by":{"0":"52"}},{"t":"usc","label":"15 U.S.C. § 1070","url":"https://www.law.cornell.edu/uscode/text/15/1070","stext":{"head":"§1070. Appeals to Trademark Trial and Appeal Board from decisions of examiners","paras":[[0,"An appeal may be taken to the Trademark Trial and Appeal Board from any final decision of the examiner in charge of the registration of marks or a final decision by an examiner in an ex parte expungement proceeding or ex parte reexamination proceeding upon the payment of the prescribed fee. The Director may reconsider, and modify or set aside, a decision of the Trademark Trial and Appeal Board under this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1070?type=usc&year=mostrecent&link-type=html"},"head":"§1070. Appeals to Trademark Trial and Appeal Board from decisions of examiners","tname":"Commerce and Trade","by":{"0":"52","1":"23"}},{"t":"usc","label":"15 U.S.C. § 1071","url":"https://www.law.cornell.edu/uscode/text/15/1071","stext":{"head":"§1071. Appeal to courts","paras":[[0,"(a) Persons entitled to appeal; United States Court of Appeals for the Federal Circuit; waiver of civil action; election of civil action by adverse party; procedure"],[0,"(1) An applicant for registration of a mark, party to an interference proceeding, party to an opposition proceeding, party to an application to register as a lawful concurrent user, party to a cancellation proceeding, a registrant who has filed an affidavit as provided in section 1058 of this title or section 1141k of this title, an applicant for renewal, or a registrant subject to an ex parte expungement proceeding or an ex parte reexamination proceeding, who is dissatisfied with the decision of the Director or Trademark Trial and Appeal Board, may appeal to the United States Court of Appeals for the Federal Circuit thereby waiving his right to proceed under subsection (b) of this section: Provided, That such appeal shall be dismissed if any adverse party to the proceeding, other than the Director, shall, within twenty days after the appellant has filed notice of appeal according to paragraph (2) of this subsection, files notice with the Director that he elects to have all further proceedings conducted as provided in subsection (b) of this section. Thereupon the appellant shall have thirty days thereafter within which to file a civil action under subsection (b) of this section, in default of which the decision appealed from shall govern the further proceedings in the case."],[0,"(2) When an appeal is taken to the United States Court of Appeals for the Federal Circuit, the appellant shall file in the United States Patent and Trademark Office a written notice of appeal directed to the Director, within such time after the date of the decision from which the appeal is taken as the Director prescribes, but in no case less than 60 days after that date."],[0,"(3) The Director shall transmit to the United States Court of Appeals for the Federal Circuit a certified list of the documents comprising the record in the United States Patent and Trademark Office. The court may request that the Director forward the original or certified copies of such documents during pendency of the appeal. In an ex parte case, the Director shall submit to that court a brief explaining the grounds for the decision of the United States Patent and Trademark Office, addressing all the issues involved in the appeal. The court shall, before hearing an appeal, give notice of the time and place of the hearing to the Director and the parties in the appeal."],[0,"(4) The United States Court of Appeals for the Federal Circuit shall review the decision from which the appeal is taken on the record before the United States Patent and Trademark Office. Upon its determination the court shall issue its mandate and opinion to the Director, which shall be entered of record in the United States Patent and Trademark Office and shall govern the further proceedings in the case. However, no final judgment shall be entered in favor of an applicant under section 1051(b) of this title before the mark is registered, if such applicant cannot prevail without establishing constructive use pursuant to section 1057(c) of this title."],[0,"(b) Civil action; persons entitled to; jurisdiction of court; status of Director; procedure"],[0,"(1) Whenever a person authorized by subsection (a) of this section to appeal to the United States Court of Appeals for the Federal Circuit, except for a registrant subject to an ex parte expungement proceeding or an ex parte reexamination proceeding, is dissatisfied with the decision of the Director or Trademark Trial and Appeal Board, said person may, unless appeal has been taken to said United States Court of Appeals for the Federal Circuit, have remedy by a civil action if commenced within such time after such decision, not less than sixty days, as the Director appoints or as provided in subsection (a) of this section. The court may adjudge that an applicant is entitled to a registration upon the application involved, that a registration involved should be canceled, or such other matter as the issues in the proceeding require, as the facts in the case may appear. Such adjudication shall authorize the Director to take any necessary action, upon compliance with the requirements of law. However, no final judgment shall be entered in favor of an applicant under section 1051(b) of this title before the mark is registered, if such applicant cannot prevail without establishing constructive use pursuant to section 1057(c) of this title."],[0,"(2) The Director shall not be made a party to an inter partes proceeding under this subsection, but he shall be notified of the filing of the complaint by the clerk of the court in which it is filed and shall have the right to intervene in the action."],[0,"(3) In any case where there is no adverse party, a copy of the complaint shall be served on the Director, and, unless the court finds the expenses to be unreasonable, all the expenses of the proceeding shall be paid by the party bringing the case, whether the final decision is in favor of such party or not. In suits brought hereunder, the record in the United States Patent and Trademark Office shall be admitted on motion of any party, upon such terms and conditions as to costs, expenses, and the further cross-examination of the witnesses as the court imposes, without prejudice to the right of any party to take further testimony. The testimony and exhibits of the record in the United States Patent and Trademark Office, when admitted, shall have the same effect as if originally taken and produced in the suit."],[0,"(4) Where there is an adverse party, such suit may be instituted against the party in interest as shown by the records of the United States Patent and Trademark Office at the time of the decision complained of, but any party in interest may become a party to the action. If there are adverse parties residing in a plurality of districts not embraced within the same State, or an adverse party residing in a foreign country, the United States District Court for the Eastern District of Virginia shall have jurisdiction and may issue summons against the adverse parties directed to the marshal of any district in which any adverse party resides. Summons against adverse parties residing in foreign countries may be served by publication or otherwise as the court directs."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1071?type=usc&year=mostrecent&link-type=html"},"head":"§1071. Appeal to courts","tname":"Commerce and Trade","by":{"0":"52","1":"23"}},{"t":"usc","label":"15 U.S.C. § 1072","url":"https://www.law.cornell.edu/uscode/text/15/1072","stext":{"head":"§1072. Registration as constructive notice of claim of ownership","paras":[[0,"Registration of a mark on the principal register provided by this chapter or under the Act of March 3, 1881, or the Act of February 20, 1905, shall be constructive notice of the registrant's claim of ownership thereof."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1072?type=usc&year=mostrecent&link-type=html"},"head":"§1072. Registration as constructive notice of claim of ownership","tname":"Commerce and Trade","by":{"0":"3, 10, 22, 27","1":"7"}},{"t":"usc","label":"15 U.S.C. § 1091","url":"https://www.law.cornell.edu/uscode/text/15/1091","stext":{"head":"§1091. Supplemental register","paras":[[0,"(a) Marks registerable"],[0,"In addition to the principal register, the Director shall keep a continuation of the register provided in paragraph (b) of section 1 of the Act of March 19, 1920, entitled \"An Act to give effect to certain provisions of the convention for the protection of trademarks and commercial names, made and signed in the city of Buenos Aires, in the Argentine Republic, August 20, 1910, and for other purposes\", to be called the supplemental register. All marks capable of distinguishing applicant's goods or services and not registrable on the principal register provided in this chapter, except those declared to be unregistrable under subsections (a), (b), (c), (d), and (e)(3) of section 1052 of this title, which are in lawful use in commerce by the owner thereof, on or in connection with any goods or services may be registered on the supplemental register upon the payment of the prescribed fee and compliance with the provisions of subsections (a) and (e) of section 1051 of this title so far as they are applicable. Nothing in this section shall prevent the registration on the supplemental register of a mark, capable of distinguishing the applicant's goods or services and not registrable on the principal register under this chapter, that is declared to be unregistrable under section 1052(e)(3) of this title, if such mark has been in lawful use in commerce by the owner thereof, on or in connection with any goods or services, since before December 8, 1993."],[0,"(b) Application and proceedings for registration"],[0,"Upon the filing of an application for registration on the supplemental register and payment of the prescribed fee the Director shall refer the application to the examiner in charge of the registration of marks, who shall cause an examination to be made and if on such examination it shall appear that the applicant is entitled to registration, the registration shall be granted. If the applicant is found not entitled to registration the provisions of subsection (b) of section 1062 of this title shall apply."],[0,"(c) Nature of mark"],[0,"For the purposes of registration on the supplemental register, a mark may consist of any trademark, symbol, label, package, configuration of goods, name, word, slogan, phrase, surname, geographical name, numeral, device, any matter that as a whole is not functional, or any combination of any of the foregoing, but such mark must be capable of distinguishing the applicant's goods or services."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1091?type=usc&year=mostrecent&link-type=html"},"head":"§1091. Supplemental register","tname":"Commerce and Trade","by":{"0":"3, 10, 22","1":"6"}},{"t":"usc","label":"15 U.S.C. § 1111","url":"https://www.law.cornell.edu/uscode/text/15/1111","by":{"0":"22, 49"}},{"t":"usc","label":"15 U.S.C. § 1115","url":"https://www.law.cornell.edu/uscode/text/15/1115","subs":["(a)","(b)"],"stext":{"head":"§1115. Registration on principal register as evidence of exclusive right to use mark; defenses","paras":[[0,"(a) Evidentiary value; defenses"],[0,"Any registration issued under the Act of March 3, 1881, or the Act of February 20, 1905, or of a mark registered on the principal register provided by this chapter and owned by a party to an action shall be admissible in evidence and shall be prima facie evidence of the validity of the registered mark and of the registration of the mark, of the registrant's ownership of the mark, and of the registrant's exclusive right to use the registered mark in commerce on or in connection with the goods or services specified in the registration subject to any conditions or limitations stated therein, but shall not preclude another person from proving any legal or equitable defense or defect, including those set forth in subsection (b), which might have been asserted if such mark had not been registered."],[0,"(b) Incontestability; defenses"],[0,"To the extent that the right to use the registered mark has become incontestable under section 1065 of this title, the registration shall be conclusive evidence of the validity of the registered mark and of the registration of the mark, of the registrant's ownership of the mark, and of the registrant's exclusive right to use the registered mark in commerce. Such conclusive evidence shall relate to the exclusive right to use the mark on or in connection with the goods or services specified in the affidavit filed under the provisions of section 1065 of this title, or in the renewal application filed under the provisions of section 1059 of this title if the goods or services specified in the renewal are fewer in number, subject to any conditions or limitations in the registration or in such affidavit or renewal application. Such conclusive evidence of the right to use the registered mark shall be subject to proof of infringement as defined in section 1114 of this title, and shall be subject to the following defenses or defects:"],[1,"(1) That the registration or the incontestable right to use the mark was obtained fraudulently; or"],[1,"(2) That the mark has been abandoned by the registrant; or"],[1,"(3) That the registered mark is being used by or with the permission of the registrant or a person in privity with the registrant, so as to misrepresent the source of the goods or services on or in connection with which the mark is used; or"],[1,"(4) That the use of the name, term, or device charged to be an infringement is a use, otherwise than as a mark, of the party's individual name in his own business, or of the individual name of anyone in privity with such party, or of a term or device which is descriptive of and used fairly and in good faith only to describe the goods or services of such party, or their geographic origin; or"],[1,"(5) That the mark whose use by a party is charged as an infringement was adopted without knowledge of the registrant's prior use and has been continuously used by such party or those in privity with him from a date prior to (A) the date of constructive use of the mark established pursuant to section 1057(c) of this title, (B) the registration of the mark under this chapter if the application for registration is filed before the effective date of the Trademark Law Revision Act of 1988, or (C) publication of the registered mark under subsection (c) of section 1062 of this title: Provided, however, That this defense or defect shall apply only for the area in which such continuous prior use is proved; or"],[1,"(6) That the mark whose use is charged as an infringement was registered and used prior to the registration under this chapter or publication under subsection (c) of section 1062 of this title of the registered mark of the registrant, and not abandoned: Provided, however, That this defense or defect shall apply only for the area in which the mark was used prior to such registration or such publication of the registrant's mark; or"],[1,"(7) That the mark has been or is being used to violate the antitrust laws of the United States; or"],[1,"(8) That the mark is functional; or"],[1,"(9) That equitable principles, including laches, estoppel, and acquiescence, are applicable."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1115?type=usc&year=mostrecent&link-type=html"},"head":"§1115. Registration on principal register as evidence of exclusive right to use mark; defenses","tname":"Commerce and Trade","by":{"0":"21, 21, 21","1":"7"}},{"t":"usc","label":"15 U.S.C. § 1117","url":"https://www.law.cornell.edu/uscode/text/15/1117","subs":["(a)"],"by":{"0":"21"}},{"t":"usc","label":"15 U.S.C. § 1124","url":"https://www.law.cornell.edu/uscode/text/15/1124","by":{"0":"27"}},{"t":"usc","label":"15 U.S.C. § 1125","url":"https://www.law.cornell.edu/uscode/text/15/1125","subs":["(a)","(a)(1)","(b)","(d)"],"stext":{"head":"§1125. False designations of origin, false descriptions, and dilution forbidden","paras":[[0,"(a) Civil action"],[0,"(1) Any person who, on or in connection with any goods or services, or any container for goods, uses in commerce any word, term, name, symbol, or device, or any combination thereof, or any false designation of origin, false or misleading description of fact, or false or misleading representation of fact, which—"],[1,"(A) is likely to cause confusion, or to cause mistake, or to deceive as to the affiliation, connection, or association of such person with another person, or as to the origin, sponsorship, or approval of his or her goods, services, or commercial activities by another person, or"],[1,"(B) in commercial advertising or promotion, misrepresents the nature, characteristics, qualities, or geographic origin of his or her or another person's goods, services, or commercial activities,"],[0,"shall be liable in a civil action by any person who believes that he or she is or is likely to be damaged by such act."],[0,"(2) As used in this subsection, the term \"any person\" includes any State, instrumentality of a State or employee of a State or instrumentality of a State acting in his or her official capacity. Any State, and any such instrumentality, officer, or employee, shall be subject to the provisions of this chapter in the same manner and to the same extent as any nongovernmental entity."],[0,"(3) In a civil action for trade dress infringement under this chapter for trade dress not registered on the principal register, the person who asserts trade dress protection has the burden of proving that the matter sought to be protected is not functional."],[0,"(b) Importation"],[0,"Any goods marked or labeled in contravention of the provisions of this section shall not be imported into the United States or admitted to entry at any customhouse of the United States. The owner, importer, or consignee of goods refused entry at any customhouse under this section may have any recourse by protest or appeal that is given under the customs revenue laws or may have the remedy given by this chapter in cases involving goods refused entry or seized."],[0,"(c) Dilution by blurring; dilution by tarnishment"],[0,"(1) Injunctive relief"],[1,"Subject to the principles of equity, the owner of a famous mark that is distinctive, inherently or through acquired distinctiveness, shall be entitled to an injunction against another person who, at any time after the owner's mark has become famous, commences use of a mark or trade name in commerce that is likely to cause dilution by blurring or dilution by tarnishment of the famous mark, regardless of the presence or absence of actual or likely confusion, of competition, or of actual economic injury."],[0,"(2) Definitions"],[1,"(A) For purposes of paragraph (1), a mark is famous if it is widely recognized by the general consuming public of the United States as a designation of source of the goods or services of the mark's owner. In determining whether a mark possesses the requisite degree of recognition, the court may consider all relevant factors, including the following:"],[2,"(i) The duration, extent, and geographic reach of advertising and publicity of the mark, whether advertised or publicized by the owner or third parties."],[2,"(ii) The amount, volume, and geographic extent of sales of goods or services offered under the mark."],[2,"(iii) The extent of actual recognition of the mark."],[2,"(iv) Whether the mark was registered under the Act of March 3, 1881, or the Act of February 20, 1905, or on the principal register."],[1,"(B) For purposes of paragraph (1), \"dilution by blurring\" is association arising from the similarity between a mark or trade name and a famous mark that impairs the distinctiveness of the famous mark. In determining whether a mark or trade name is likely to cause dilution by blurring, the court may consider all relevant factors, including the following:"],[2,"(i) The degree of similarity between the mark or trade name and the famous mark."],[2,"(ii) The degree of inherent or acquired distinctiveness of the famous mark."],[2,"(iii) The extent to which the owner of the famous mark is engaging in substantially exclusive use of the mark."],[2,"(iv) The degree of recognition of the famous mark."],[2,"(v) Whether the user of the mark or trade name intended to create an association with the famous mark."],[2,"(vi) Any actual association between the mark or trade name and the famous mark."],[1,"(C) For purposes of paragraph (1), \"dilution by tarnishment\" is association arising from the similarity between a mark or trade name and a famous mark that harms the reputation of the famous mark."],[0,"(3) Exclusions"],[1,"The following shall not be actionable as dilution by blurring or dilution by tarnishment under this subsection:"],[2,"(A) Any fair use, including a nominative or descriptive fair use, or facilitation of such fair use, of a famous mark by another person other than as a designation of source for the person's own goods or services, including use in connection with—"],[3,"(i) advertising or promotion that permits consumers to compare goods or services; or"],[3,"(ii) identifying and parodying, criticizing, or commenting upon the famous mark owner or the goods or services of the famous mark owner."],[2,"(B) All forms of news reporting and news commentary."],[2,"(C) Any noncommercial use of a mark."],[0,"(4) Burden of proof"],[1,"In a civil action for trade dress dilution under this chapter for trade dress not registered on the principal register, the person who asserts trade dress protection has the burden of proving that—"],[2,"(A) the claimed trade dress, taken as a whole, is not functional and is famous; and"],[2,"(B) if the claimed trade dress includes any mark or marks registered on the principal register, the unregistered matter, taken as a whole, is famous separate and apart from any fame of such registered marks."],[0,"(5) Additional remedies"],[1,"In an action brought under this subsection, the owner of the famous mark shall be entitled to injunctive relief as set forth in section 1116 of this title. The owner of the famous mark shall also be entitled to the remedies set forth in sections 1117(a) and 1118 of this title, subject to the discretion of the court and the principles of equity if—"],[2,"(A) the mark or trade name that is likely to cause dilution by blurring or dilution by tarnishment was first used in commerce by the person against whom the injunction is sought after October 6, 2006; and"],[2,"(B) in a claim arising under this subsection—"],[3,"(i) by reason of dilution by blurring, the person against whom the injunction is sought willfully intended to trade on the recognition of the famous mark; or"],[3,"(ii) by reason of dilution by tarnishment, the person against whom the injunction is sought willfully intended to harm the reputation of the famous mark."],[0,"(6) Ownership of valid registration a complete bar to action"],[1,"The ownership by a person of a valid registration under the Act of March 3, 1881, or the Act of February 20, 1905, or on the principal register under this chapter shall be a complete bar to an action against that person, with respect to that mark, that—"],[2,"(A) is brought by another person under the common law or a statute of a State; and"],[2,"(B)(i) seeks to prevent dilution by blurring or dilution by tarnishment; or"],[2,"(ii) asserts any claim of actual or likely damage or harm to the distinctiveness or reputation of a mark, label, or form of advertisement."],[0,"(7) Savings clause"],[1,"Nothing in this subsection shall be construed to impair, modify, or supersede the applicability of the patent laws of the United States."],[0,"(d) Cyberpiracy prevention"],[0,"(1)(A) A person shall be liable in a civil action by the owner of a mark, including a personal name which is protected as a mark under this section, if, without regard to the goods or services of the parties, that person—"],[1,"(i) has a bad faith intent to profit from that mark, including a personal name which is protected as a mark under this section; and"],[1,"(ii) registers, traffics in, or uses a domain name that—"],[2,"(I) in the case of a mark that is distinctive at the time of registration of the domain name, is identical or confusingly similar to that mark;"],[2,"(II) in the case of a famous mark that is famous at the time of registration of the domain name, is identical or confusingly similar to or dilutive of that mark; or"],[2,"(III) is a trademark, word, or name protected by reason of section 706 of title 18 or section 220506 of title 36."],[0,"(B)(i) In determining whether a person has a bad faith intent described under subparagraph (A), a court may consider factors such as, but not limited to—"],[1,"(I) the trademark or other intellectual property rights of the person, if any, in the domain name;"],[1,"(II) the extent to which the domain name consists of the legal name of the person or a name that is otherwise commonly used to identify that person;"],[1,"(III) the person's prior use, if any, of the domain name in connection with the bona fide offering of any goods or services;"],[1,"(IV) the person's bona fide noncommercial or fair use of the mark in a site accessible under the domain name;"],[1,"(V) the person's intent to divert consumers from the mark owner's online location to a site accessible under the domain name that could harm the goodwill represented by the mark, either for commercial gain or with the intent to tarnish or disparage the mark, by creating a likelihood of confusion as to the source, sponsorship, affiliation, or endorsement of the site;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1125?type=usc&year=mostrecent&link-type=html"},"head":"§1125. False designations of origin, false descriptions, and dilution forbidden","tname":"Commerce and Trade","by":{"0":"22, 22, 22, 22, 22","1":"3"}},{"t":"usc","label":"15 U.S.C. § 1127","url":"https://www.law.cornell.edu/uscode/text/15/1127","stext":{"head":"§1127. Construction and definitions; intent of chapter","paras":[[0,"In the construction of this chapter, unless the contrary is plainly apparent from the context—"],[0,"The United States includes and embraces all territory which is under its jurisdiction and control."],[0,"The word \"commerce\" means all commerce which may lawfully be regulated by Congress."],[0,"The term \"principal register\" refers to the register provided for by sections 1051 to 1072 of this title, and the term \"supplemental register\" refers to the register provided for by sections 1091 to 1096 of this title."],[0,"The term \"person\" and any other word or term used to designate the applicant or other entitled to a benefit or privilege or rendered liable under the provisions of this chapter includes a juristic person as well as a natural person. The term \"juristic person\" includes a firm, corporation, union, association, or other organization capable of suing and being sued in a court of law."],[0,"The term \"person\" also includes the United States, any agency or instrumentality thereof, or any individual, firm, or corporation acting for the United States and with the authorization and consent of the United States. The United States, any agency or instrumentality thereof, and any individual, firm, or corporation acting for the United States and with the authorization and consent of the United States, shall be subject to the provisions of this chapter in the same manner and to the same extent as any nongovernmental entity."],[0,"The term \"person\" also includes any State, any instrumentality of a State, and any officer or employee of a State or instrumentality of a State acting in his or her official capacity. Any State, and any such instrumentality, officer, or employee, shall be subject to the provisions of this chapter in the same manner and to the same extent as any nongovernmental entity."],[0,"The terms \"applicant\" and \"registrant\" embrace the legal representatives, predecessors, successors and assigns of such applicant or registrant."],[0,"The term \"Director\" means the Under Secretary of Commerce for Intellectual Property and Director of the United States Patent and Trademark Office."],[0,"The term \"related company\" means any person whose use of a mark is controlled by the owner of the mark with respect to the nature and quality of the goods or services on or in connection with which the mark is used."],[0,"The terms \"trade name\" and \"commercial name\" mean any name used by a person to identify his or her business or vocation."],[0,"The term \"trademark\" includes any word, name, symbol, or device, or any combination thereof—"],[1,"(1) used by a person, or"],[1,"(2) which a person has a bona fide intention to use in commerce and applies to register on the principal register established by this chapter,"],[0,"to identify and distinguish his or her goods, including a unique product, from those manufactured or sold by others and to indicate the source of the goods, even if that source is unknown."],[0,"The term \"service mark\" means any word, name, symbol, or device, or any combination thereof—"],[1,"(1) used by a person, or"],[1,"(2) which a person has a bona fide intention to use in commerce and applies to register on the principal register established by this chapter,"],[0,"to identify and distinguish the services of one person, including a unique service, from the services of others and to indicate the source of the services, even if that source is unknown. Titles, character names, and other distinctive features of radio or television programs may be registered as service marks notwithstanding that they, or the programs, may advertise the goods of the sponsor."],[0,"The term \"certification mark\" means any word, name, symbol, or device, or any combination thereof—"],[1,"(1) used by a person other than its owner, or"],[1,"(2) which its owner has a bona fide intention to permit a person other than the owner to use in commerce and files an application to register on the principal register established by this chapter,"],[0,"to certify regional or other origin, material, mode of manufacture, quality, accuracy, or other characteristics of such person's goods or services or that the work or labor on the goods or services was performed by members of a union or other organization."],[0,"The term \"collective mark\" means a trademark or service mark—"],[1,"(1) used by the members of a cooperative, an association, or other collective group or organization, or"],[1,"(2) which such cooperative, association, or other collective group or organization has a bona fide intention to use in commerce and applies to register on the principal register established by this chapter,"],[0,"and includes marks indicating membership in a union, an association, or other organization."],[0,"The term \"mark\" includes any trademark, service mark, collective mark, or certification mark."],[0,"The term \"use in commerce\" means the bona fide use of a mark in the ordinary course of trade, and not made merely to reserve a right in a mark. For purposes of this chapter, a mark shall be deemed to be in use in commerce—"],[1,"(1) on goods when—"],[2,"(A) it is placed in any manner on the goods or their containers or the displays associated therewith or on the tags or labels affixed thereto, or if the nature of the goods makes such placement impracticable, then on documents associated with the goods or their sale, and"],[2,"(B) the goods are sold or transported in commerce, and"],[1,"(2) on services when it is used or displayed in the sale or advertising of services and the services are rendered in commerce, or the services are rendered in more than one State or in the United States and a foreign country and the person rendering the services is engaged in commerce in connection with the services."],[0,"A mark shall be deemed to be \"abandoned\" if either of the following occurs:"],[1,"(1) When its use has been discontinued with intent not to resume such use. Intent not to resume may be inferred from circumstances. Nonuse for 3 consecutive years shall be prima facie evidence of abandonment. \"Use\" of a mark means the bona fide use of such mark made in the ordinary course of trade, and not made merely to reserve a right in a mark."],[1,"(2) When any course of conduct of the owner, including acts of omission as well as commission, causes the mark to become the generic name for the goods or services on or in connection with which it is used or otherwise to lose its significance as a mark. Purchaser motivation shall not be a test for determining abandonment under this paragraph."],[0,"The term \"colorable imitation\" includes any mark which so resembles a registered mark as to be likely to cause confusion or mistake or to deceive."],[0,"The term \"registered mark\" means a mark registered in the United States Patent and Trademark Office under this chapter or under the Act of March 3, 1881, or the Act of February 20, 1905, or the Act of March 19, 1920. The phrase \"marks registered in the Patent and Trademark Office\" means registered marks."],[0,"The term \"Act of March 3, 1881\", \"Act of February 20, 1905\", or \"Act of March 19, 1920\", means the respective Act as amended."],[0,"A \"counterfeit\" is a spurious mark which is identical with, or substantially indistinguishable from, a registered mark."],[0,"The term \"domain name\" means any alphanumeric designation which is registered with or assigned by any domain name registrar, domain name registry, or other domain name registration authority as part of an electronic address on the Internet."],[0,"The term \"Internet\" has the meaning given that term in section 230(f)(1) of title 47."],[0,"Words used in the singular include the plural and vice versa."],[0,"The intent of this chapter is to regulate commerce within the control of Congress by making actionable the deceptive and misleading use of marks in such commerce; to protect registered marks used in such commerce from interference by State, or territorial legislation; to protect persons engaged in such commerce against unfair competition; to prevent fraud and deception in such commerce by the use of reproductions, copies, counterfeits, or colorable imitations of registered marks; and to provide rights and remedies stipulated by treaties and conventions respecting trademarks, trade names, and unfair competition entered into between the United States and foreign nations."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1127?type=usc&year=mostrecent&link-type=html"},"head":"§1127. Construction and definitions; intent of chapter","tname":"Commerce and Trade","by":{"0":"22","1":"16, 21"}},{"t":"usc","label":"15 U.S.C. § 1141b","url":"https://www.law.cornell.edu/uscode/text/15/1141b","stext":{"head":"§1141b. Certification of the international application","paras":[[0,"(a) Certification procedure"],[0,"Upon the filing of an application for international registration and payment of the prescribed fees, the Director shall examine the international application for the purpose of certifying that the information contained in the international application corresponds to the information contained in the basic application or basic registration at the time of the certification."],[0,"(b) Transmittal"],[0,"Upon examination and certification of the international application, the Director shall transmit the international application to the International Bureau."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1141b?type=usc&year=mostrecent&link-type=html"},"head":"§1141b. Certification of the international application","tname":"Commerce and Trade","by":{"0":"22","1":"7"}},{"t":"usc","label":"18 U.S.C. § 871","url":"https://www.law.cornell.edu/uscode/text/18/871","by":{"0":"45"}},{"t":"usc","label":"20 U.S.C. § 954","url":"https://www.law.cornell.edu/uscode/text/20/954","subs":["(d)(1)"],"stext":{"head":"§954. National Endowment for the Arts","paras":[[0,"(a) Establishment"],[0,"There is established within the Foundation a National Endowment for the Arts."],[0,"(b) Chairperson of the Endowment; term of office; vacancies"],[0,"(1) The Endowment shall be headed by a chairperson, to be known as the Chairperson of the National Endowment for the Arts, who shall be appointed by the President, by and with the advice and consent of the Senate."],[0,"(2) The term of office of the Chairperson shall be four years and the Chairperson shall be eligible for reappointment. The provisions of this subsection shall apply to any person appointed to fill a vacancy in the office of Chairperson. Upon expiration of the Chairperson's term of office the Chairperson shall serve until the Chairperson's successor shall have been appointed and shall have qualified."],[0,"(c) Program of contracts, grants-in-aid, or loans to groups and individuals for projects and productions; traditionally underrepresented recipients of financial assistance"],[0,"The Chairperson, with the advice of the National Council on the Arts, is authorized to establish and carry out a program of contracts with, or grants-in-aid or loans to, groups or, in appropriate cases, individuals of exceptional talent engaged in or concerned with the arts, for the purpose of enabling them to provide or support—"],[1,"(1) projects and productions which have substantial national or international artistic and cultural significance, giving emphasis to American creativity and cultural diversity and to the maintenance and encouragement of professional excellence;"],[1,"(2) projects and productions, meeting professional standards or standards of authenticity or tradition, irrespective of origin, which are of significant merit and which, without such assistance, would otherwise be unavailable to our citizens for geographic or economic reasons;"],[1,"(3) projects and productions that will encourage and assist artists and enable them to achieve wider distribution of their works, to work in residence at an educational or cultural institution, or to achieve standards of professional excellence;"],[1,"(4) projects and productions which have substantial artistic and cultural significance and that reach, or reflect the culture of, a minority, inner city, rural, or tribal community;"],[1,"(5) projects and productions that will encourage public knowledge, education, understanding, and appreciation of the arts;"],[1,"(6) workshops that will encourage and develop the appreciation and enjoyment of the arts by our citizens;"],[1,"(7) programs for the arts at the local level;"],[1,"(8) projects that enhance managerial and organizational skills and capabilities;"],[1,"(9) projects, productions, and workshops of the kinds described in paragraphs (1) through (8) through film, radio, video, and similar media, for the purpose of broadening public access to the arts; and"],[1,"(10) other relevant projects, including surveys, research, planning, and publications relating to the purposes of this subsection."],[0,"In the case of publications under paragraph (10) of this subsection such publications may be supported without regard for the provisions of section 501 of title 44 only if the Chairperson consults with the Joint Committee on Printing of the Congress and the Chairperson submits to the Committee on Labor and Human Resources of the Senate and the Committee on Education and Labor of the House of Representatives a report justifying any exemption from such section 501. Any loans made by the Chairperson under this subsection shall be made in accordance with terms and conditions approved by the Secretary of the Treasury. In selecting individuals and groups of exceptional talent as recipients of financial assistance to be provided under this subsection, the Chairperson shall give particular regard to artists and artistic groups that have traditionally been underrepresented."],[0,"(d) Application for payment; regulations and procedures"],[0,"No payment shall be made under this section except upon application therefor which is submitted to the National Endowment for the Arts in accordance with regulations issued and procedures established by the Chairperson. In establishing such regulations and procedures, the Chairperson shall ensure that—"],[1,"(1) artistic excellence and artistic merit are the criteria by which applications are judged, taking into consideration general standards of decency and respect for the diverse beliefs and values of the American public; and"],[1,"(2) applications are consistent with the purposes of this section. Such regulations and procedures shall clearly indicate that obscenity is without artistic merit, is not protected speech, and shall not be funded. Projects, productions, workshops, and programs that are determined to be obscene are prohibited from receiving financial assistance under this subchapter from the National Endowment for the Arts."],[0,"The disapproval or approval of an application by the Chairperson shall not be construed to mean, and shall not be considered as evidence that, the project, production, workshop, or program for which the applicant requested financial assistance is or is not obscene."],[0,"(e) Limitation on amount of grant to group; grants and contracts of the National Endowment for the Arts"],[0,"The total amount of any grant to any group pursuant to subsection (c) of this section shall not exceed 50 per centum of the total cost of such project or production, except that not more than 20 per centum of the funds allotted by the National Endowment for the Arts for the purposes of subsection (c) for any fiscal year may be available for grants and contracts in that fiscal year without regard to such limitation."],[0,"(f) Eligibility for financial assistance"],[0,"Any group shall be eligible for financial assistance pursuant to this section only if (1) no part of its net earnings inures to the benefit of any private stockholder or stockholders, or individual or individuals, and (2) donations to such group are allowable as a charitable contribution under the standards of subsection (c) of section 170 of title 26."],[0,"(g) Grants to States for projects and productions; applications; terms and conditions of State plans; minimum allotments; excess appropriations; cost limitations; grants to regional groups; non-Federal funding; definitions"],[0,"(1) The Chairperson, with the advice of the National Council on the Arts, is authorized to establish and carry out a program of grants-in-aid to assist the several States in supporting existing projects and productions which meet the standards enumerated in subsection (c) of this section, and in developing projects and productions in the arts in such a manner as will furnish adequate programs, facilities, and services in the arts to all the people and communities in each of the several States."],[0,"(2) In order to receive assistance under this subsection in any fiscal year, a State shall submit an application for such grants at such time as shall be specified by the Chairperson and accompany such application with a plan which the Chairperson finds—"],[1,"(A) designates or provides for the establishment of a State agency (hereinafter in this section referred to as the \"State agency\") as the sole agency for the administration of the State plan;"],[1,"(B) provides that funds paid to the State under this subsection will be expended solely on projects and productions approved by the State agency which carry out one or more of the objectives of subsection (c);"],[1,"(C) provides that the State agency will make such reports, in such form and containing such information, as the Chairperson may from time to time require, including a description of the progress made toward achieving the goals of the State plan;"],[1,"(D) provides—"],[2,"(i) assurances that the State agency has held, after reasonable notice, public meetings in the State to allow all groups of artists, interested organizations, and the public to present views and make recommendations regarding the State plan; and"],[2,"(ii) a summary of such recommendations and the State agency's response to such recommendations; and"],[1,"(E) contains—"],[2,"(i) a description of the level of participation during the most recent preceding year for which information is available by artists, artists' organizations, and arts organizations in projects and productions for which financial assistance is provided under this subsection;"],[2,"(ii) for the most recent preceding year for which information is available, a description of the extent projects and productions receiving financial assistance from the State arts agency are available to all people and communities in the State; and"],[2,"(iii) a description of projects and productions receiving financial assistance under this subsection that exist or are being developed to secure wider participation of artists, artists' organizations, and arts organizations identified under clause (i) of this subparagraph or that address the availability of the arts to all people or communities identified under clause (ii) of this subparagraph."],[0,"No application may be approved unless the accompanying plan satisfies the requirements specified in this subsection."],[0,"(3) Of the sums available to carry out this subsection for any fiscal year, each State which has a plan approved by the Chairperson shall be allotted at least $200,000. If the sums appropriated are insufficient to make the allotments under the preceding sentence in full, such sums shall be allotted among such States in equal amounts. In any case where the sums available to carry out this subsection for any fiscal year are in excess of the amount required to make the allotments under the first sentence of this paragraph—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/20/954?type=usc&year=mostrecent&link-type=html"},"head":"§954. National Endowment for the Arts","tname":"Education","by":{"0":"16","1":"10"}},{"t":"usc","label":"22 U.S.C. § 7631","url":"https://www.law.cornell.edu/uscode/text/22/7631","by":{"0":"33"}},{"t":"usc","label":"35 U.S.C. § 42","url":"https://www.law.cornell.edu/uscode/text/35/42","subs":["(c)(1)","(c)(2)"],"by":{"0":"42, 42"}},{"t":"case","label":"Brown v. Entertainment Merchs. Ass’n","cite":"564 U.S. 786","y":2011,"id":"2010/08-1448","sc":1,"sum":"The Court held that video games, including violent ones, are protected speech under the First Amendment.","sumSrc":"Oyez","by":{"1":"5"}},{"t":"case","label":"Chevron U.S.A. Inc. v. NRDC, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"Cornelius v. NAACP Legal Def. & Educ. Fund, Inc.","cite":"473 U.S. 788","y":1985,"id":"1984/84-312","sc":1,"sum":"By Executive Order, participation in the Combined Federal Campaign (CFC), a charity drive aimed at federal employees, is limited to voluntary, tax-exempt, nonprofit charitable agencies that provide direct health und welfare services to individuals or their families, and legal defense and political advocacy organizations are specifically excluded. Participating organizations confine their fundraising activities to a …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"4"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"FCC v. Pacifica Found.","cite":"438 U.S. 726","y":1978,"id":"1977/77-528","sc":1,"ar":1,"sum":"The Court held that audience, medium, time of day and method of transmission were all relevant factors in determining what speech is protected by the First Amendment.","sumSrc":"Oyez","by":{"1":"5, 11"}},{"t":"case","label":"Forsyth Cnty. v. Nationalist Movement","cite":"505 U.S. 123","y":1992,"id":"1991/91-538","sc":1,"sum":"The Court held that an ordinance that permits a government administrator to vary the fee for assembling or parading to reflect the estimated cost of maintaining public order violated the free-speech guarantees under the First and Fourteenth Amendments.","sumSrc":"Oyez","by":{"1":"4"}},{"t":"case","label":"Greyhound Corp. v. Both Worlds Inc.","cite":"6 U.S.P.Q.2d 1635","y":1988,"court":"T.T.A.B. Mar. 30","url":"https://www.courtlistener.com/c/U.S.P.Q.2d/6/1635/","by":{"1":"8"}},{"t":"case","label":"Holder v. Humanitarian Law Project","cite":"561 U.S. 1","y":2010,"id":"2009/08-1498","sc":1,"sum":"The Court held that sections of the Antiterrorism and Effective Death Penalty Act were not unconstitutionally vague in a lawsuit that named the Kurdistan Workers Party and Liberation Tigers of Tamil Eelam.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"Miller v. California","cite":"413 U.S. 15","y":1973,"id":"1971/70-73","sc":1,"ar":1,"sum":"The Court found that \"obscene materials\" do not have First Amendment protection.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Perry v. McDonald","cite":"280 F.3d 159","y":2011,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/280/159/","by":{"1":"11, 15"}},{"t":"case","label":"Perry Educ. Ass’n v. Perry Local Educators’ Ass’n","cite":"460 U.S. 37","y":1983,"id":"1982/81-896","sc":1,"sum":"Justice Byron White delivered the opinion of a 5-4 court. The school board chose to grant exclusive access to the official teachers union in order to facilitate a collective-bargaining agreement. It did not act to suppress the speech of rival teachers unions. The school board entrusted PEA with obligations as the sole representative of teachers that would require the use of the mail system.","sumSrc":"Oyez","by":{"1":"10"}},{"t":"case","label":"Reed v. Town of Gilbert","cite":"135 S. Ct. 2218","y":2015,"id":"2014/13-502","sc":1,"sum":"The Court decided that extra restrictions placed on signs describing the location of nonprofit events do not survive strict scrutiny and are therefore unconstitutional.","sumSrc":"Oyez","by":{"1":"5"}},{"t":"case","label":"Simon & Schuster, Inc. v. Members of the N.Y. State Crime Victims Bd.","cite":"502 U.S. 105","y":1991,"id":"1991/90-1059","sc":1,"ar":1,"sum":"The Court concluded that \"New York has singled out speech on a particular subject for a financial burden that it places on no other speech and no other income.\" This discrimination could only be justified if the state could show \"that its regulation is necessary to serve a compelling state interest and is narrowly drawn to achieve that end\" (Arkansas Writers' Project, Inc. v. Ragland, 481 U.S. 221, 231 (1987)).","sumSrc":"Oyez","by":{"1":"5, 12"}},{"t":"case","label":"Snyder v. Phelps","cite":"562 U.S. 443","y":2011,"id":"2010/09-751","sc":1,"sum":"The Court held that the Westboro Baptist Church was protected under the First Amendment while picketing a military funeral.","sumSrc":"Oyez","by":{"1":"5"}},{"t":"case","label":"Sorrell v. IMS Health Inc.","cite":"564 U.S. 552","y":2011,"id":"2010/10-779","sc":1,"ar":1,"sum":"The Court held that a Vermont statute banning the sale, transmission or use of prescription drug user data violated protected speech of the pharmaceutical research companies, manufacturers and others who use that data.","sumSrc":"Oyez","by":{"1":"4, 5"}},{"t":"case","label":"Texas v. Johnson","cite":"491 U.S. 397","y":1989,"id":"1988/88-155","sc":1,"sum":"The Court held that burning the American Flag is protected free speech under the First Amendment.","sumSrc":"Oyez","by":{"1":"5"}},{"t":"case","label":"United States v. Stevens","cite":"559 U.S. 460","y":2010,"id":"2009/08-769","sc":1,"sum":"The Court ruled that 18 U.S.C. Section 48 was unconstitutional under the Free Speech Clause of the First Amendment.","sumSrc":"Oyez","by":{"1":"13"}},{"t":"usc","label":"17 U.S.C. § 102","url":"https://www.law.cornell.edu/uscode/text/17/102","by":{"1":"16"}},{"t":"usc","label":"18 U.S.C. § 48","url":"https://www.law.cornell.edu/uscode/text/18/48","by":{"1":"13"}}]};